`timescale 1ns / 1ps
// Repro A: the pwm period must be PERIOD (8) clock cycles.
module tb_pwm_period;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    n;
    integer    i;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    // Wait for a rising edge of pwm, sampled at negedge clk; n = negedges waited.
    task wait_rise(output integer cnt);
        reg p;
        begin
            cnt = 0;
            p = pwm;
            @(negedge clk); cnt = cnt + 1;
            while (!(pwm === 1'b1 && p === 1'b0) && cnt < 64) begin
                p = pwm;
                @(negedge clk); cnt = cnt + 1;
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        wait_rise(n);              // synchronise to a period start
        for (i = 0; i < 3; i = i + 1) begin
            wait_rise(n);
            if (n == 8) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK period[%0d]: expected 8 cycles, got %0d", i, n);
            end
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===
