// Repro B: with constant duty, pwm must be high for exactly `duty` cycles per period.
module tb_pwm_pulse_width;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd3;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    n;
    integer    w;
    integer    i;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task wait_rise(output integer cnt);
        reg p;
        begin
            cnt = 0;
            p = pwm;
            @(negedge clk); cnt = cnt + 1;
            while (!(pwm === 1'b1 && p === 1'b0) && cnt < 64) begin
                p = pwm;
                @(negedge clk); cnt = cnt + 1;
            end
        end
    endtask

    // Called at the negedge where the rise was seen; ends at the negedge where pwm is low.
    task high_width(output integer cnt);
        begin
            cnt = 1;
            @(negedge clk);
            while (pwm === 1'b1 && cnt < 64) begin
                cnt = cnt + 1;
                @(negedge clk);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        wait_rise(n);              // first rise after reset, discard
        for (i = 0; i < 3; i = i + 1) begin
            wait_rise(n);
            high_width(w);
            if (w == 3) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $display("CHECK width[%0d]: duty=3, expected high 3 cycles, got %0d", i, w);
            end
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
