// Repro C: a change of duty in the middle of a period must not affect that period;
// it takes effect in the next period.
module tb_pwm_duty_update;
    reg        clk  = 1'b0;
    reg        rst  = 1'b1;
    reg  [3:0] duty = 4'd2;
    wire       pwm;
    integer    passed = 0;
    integer    failed = 0;
    integer    n;
    integer    per;
    integer    w0;
    integer    lw;
    integer    w1;
    reg [8*64-1:0] nonce;

    pwm_gen #(.PERIOD(8)) dut (.clk(clk), .rst(rst), .duty(duty), .pwm(pwm));

    always #5 clk = ~clk;

    task wait_rise(output integer cnt);
        reg p;
        begin
            cnt = 0;
            p = pwm;
            @(negedge clk); cnt = cnt + 1;
            while (!(pwm === 1'b1 && p === 1'b0) && cnt < 64) begin
                p = pwm;
                @(negedge clk); cnt = cnt + 1;
            end
        end
    endtask

    task high_width(output integer cnt);
        begin
            cnt = 1;
            @(negedge clk);
            while (pwm === 1'b1 && cnt < 64) begin
                cnt = cnt + 1;
                @(negedge clk);
            end
        end
    endtask

    // Called at the negedge where pwm went low; ends at the negedge where pwm rose.
    task low_width(output integer cnt);
        begin
            cnt = 1;
            @(negedge clk);
            while (pwm === 1'b0 && cnt < 64) begin
                cnt = cnt + 1;
                @(negedge clk);
            end
        end
    endtask

    initial begin
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        repeat (3) @(negedge clk);
        rst = 1'b0;
        wait_rise(n);              // first rise after reset
        wait_rise(per);            // reference period with constant duty
        high_width(w0);            // now at the negedge just after the fall
        duty = 4'd6;               // change duty in the middle of the period
        low_width(lw);             // now at the negedge where the next rise was seen
        if (w0 + lw == per) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK hold: mid-period duty change altered the current period: high %0d + low %0d != period %0d", w0, lw, per);
        end
        high_width(w1);
        if (w1 > w0) begin
            passed = passed + 1;
        end else begin
            failed = failed + 1;
            $display("CHECK apply: new duty not in effect next period: high %0d, previous %0d", w1, w0);
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule
=== END FILE ===

